+use anyhow::{anyhow, Context, Result};
+use serde::Deserialize;
+use x509_cert::der::Decode;
+use x509_cert::Certificate;
+
+/// Parsed representation of the JSON QE Identity structure returned by PCCS.
+#[derive(Debug, Deserialize)]
+pub struct QeIdentityBody {
+    #[serde(rename = "issueDate")]
+    pub issue_date: String,
+    #[serde(rename = "nextUpdate")]
+    pub next_update: String,
+    #[serde(rename = "miscselect")]
+    pub misc_select: String,
+    #[serde(rename = "miscselectMask")]
+    pub misc_select_mask: String,
+    #[serde(rename = "attributes")]
+    pub attributes: String,
+    #[serde(rename = "attributesMask")]
+    pub attributes_mask: String,
+    #[serde(rename = "mrsigner")]
+    pub mrsigner: String,
+    #[serde(rename = "isvprodid")]
+    pub isv_prod_id: u16,
+    #[serde(rename = "tcbLevels")]
+    pub tcb_levels: Vec<TcbLevel>,
+}
+
+#[derive(Debug, Deserialize)]
+pub struct TcbLevel {
+    pub tcb: Tcb,
+    #[serde(rename = "tcbStatus")]
+    pub tcb_status: String,
+    #[serde(rename = "tcbDate")]
+    pub tcb_date: String,
+}
+
+#[derive(Debug, Deserialize)]
+pub struct Tcb {
+    pub isvsvn: u16,
+}
+
+fn hex_decode(s: &str) -> Result<Vec<u8>> {
+    hex::decode(s).context("Invalid hex encoding")
+}
+
+/// Verifies the ECDSA signature over the raw `qe_identity` JSON body using
+/// the public key extracted from `signing_cert`. This closes the gap where
+/// forged QE identity data could be accepted without any cryptographic
+/// check against the certificate chain rooted in the Intel root CA.
+pub fn verify_qe_identity_signature(
+    qe_identity_raw: &[u8],
+    signature: &[u8],
+    signing_cert: &Certificate,
+) -> Result<()> {
+    use p256::ecdsa::signature::Verifier;
+    use p256::ecdsa::{Signature, VerifyingKey};
+
+    let pubkey_bytes = signing_cert
+        .tbs_certificate
+        .subject_public_key_info
+        .subject_public_key
+        .as_bytes()
+        .ok_or_else(|| anyhow!("Missing public key in signing certificate"))?;
+
+    let verifying_key = VerifyingKey::from_sec1_bytes(pubkey_bytes)
+        .context("Failed to parse signing certificate public key")?;
+
+    if signature.len() != 64 {
+        return Err(anyhow!("Invalid QE identity signature length"));
+    }
+    let sig = Signature::from_bytes(signature.into())
+        .context("Failed to parse QE identity signature")?;
+
+    verifying_key
+        .verify(qe_identity_raw, &sig)
+        .map_err(|e| anyhow!("QE identity signature verification failed: {e}"))
+}
+
+/// Enforces the policy constraints described by the QE Identity structure
+/// against the actual QE report contained in the quote. This ensures that
+/// only an enclave matching Intel's whitelisted QE (mrsigner, isvprodid,
+/// attributes/miscselect masks, and isvsvn/tcb status) is accepted.
+pub fn verify_qe_identity(
+    qe_identity_raw: &[u8],
+    qe_report: &crate::quote::EnclaveReport,
+    now: u64,
+) -> Result<()> {
+    let identity: QeIdentityBody =
+        serde_json::from_slice(qe_identity_raw).context("Failed to parse QE identity JSON")?;
+
+    let issue_date = chrono::DateTime::parse_from_rfc3339(&identity.issue_date)
+        .context("Invalid issueDate in QE identity")?
+        .timestamp() as u64;
+    let next_update = chrono::DateTime::parse_from_rfc3339(&identity.next_update)
+        .context("Invalid nextUpdate in QE identity")?
+        .timestamp() as u64;
+
+    if now < issue_date || now > next_update {
+        return Err(anyhow!("QE identity collateral has expired or is not yet valid"));
+    }
+
+    let mrsigner = hex_decode(&identity.mrsigner)?;
+    if mrsigner != qe_report.mrsigner {
+        return Err(anyhow!("QE report mrsigner does not match QE identity"));
+    }
+
+    if identity.isv_prod_id != qe_report.isv_prod_id {
+        return Err(anyhow!("QE report isvprodid does not match QE identity"));
+    }
+
+    let attributes = hex_decode(&identity.attributes)?;
+    let attributes_mask = hex_decode(&identity.attributes_mask)?;
+    for i in 0..attributes.len().min(qe_report.attributes.len()) {
+        if (qe_report.attributes[i] & attributes_mask[i]) != (attributes[i] & attributes_mask[i]) {
+            return Err(anyhow!("QE report attributes do not match QE identity"));
+        }
+    }
+
+    let misc_select = hex_decode(&identity.misc_select)?;
+    let misc_select_mask = hex_decode(&identity.misc_select_mask)?;
+    let qe_misc_select = qe_report.misc_select.to_le_bytes();
+    for i in 0..misc_select.len().min(qe_misc_select.len()) {
+        if (qe_misc_select[i] & misc_select_mask[i]) != (misc_select[i] & misc_select_mask[i]) {
+            return Err(anyhow!("QE report miscselect does not match QE identity"));
+        }
+    }
+
+    let matched_level = identity
+        .tcb_levels
+        .iter()
+        .find(|level| qe_report.isv_svn >= level.tcb.isvsvn)
+        .ok_or_else(|| anyhow!("No matching TCB level found for QE report isvsvn"))?;
+
+    if matched_level.tcb_status != "UpToDate" {
+        return Err(anyhow!(
+            "QE TCB status is not up to date: {}",
+            matched_level.tcb_status
+        ));
+    }
+
+    Ok(())
+}
