+namespace {
+
+// Returns the SecStaticCodeRef for the given path, or NULL on failure.
+SecStaticCodeRef CreateStaticCode(NSString* path) {
+  NSURL* url = [NSURL fileURLWithPath:path];
+  SecStaticCodeRef static_code = NULL;
+  OSStatus status =
+      SecStaticCodeCreateWithPath((__bridge CFURLRef)url,
+                                   kSecCSDefaultFlags, &static_code);
+  if (status != errSecSuccess) {
+    return NULL;
+  }
+  return static_code;
+}
+
+// Extracts the designated requirement string for a given code object.
+// Returns nil on failure.
+NSString* DesignatedRequirement(SecStaticCodeRef code) {
+  SecRequirementRef requirement = NULL;
+  OSStatus status = SecCodeCopyDesignatedRequirement(
+      code, kSecCSDefaultFlags, &requirement);
+  if (status != errSecSuccess || requirement == NULL) {
+    return nil;
+  }
+
+  CFStringRef requirement_string = NULL;
+  status = SecRequirementCopyString(requirement, kSecCSDefaultFlags,
+                                     &requirement_string);
+  CFRelease(requirement);
+  if (status != errSecSuccess || requirement_string == NULL) {
+    return nil;
+  }
+
+  NSString* result = [(__bridge NSString*)requirement_string copy];
+  CFRelease(requirement_string);
+  return result;
+}
+
+}  // namespace
+
+BOOL ElectronSquirrelUpdateValidate(NSString* update_bundle_path,
+                                     NSError** error) {
+  NSString* running_app_path = [[NSBundle mainBundle] bundlePath];
+
+  SecStaticCodeRef running_code = CreateStaticCode(running_app_path);
+  SecStaticCodeRef update_code = CreateStaticCode(update_bundle_path);
+
+  if (running_code == NULL || update_code == NULL) {
+    if (running_code)
+      CFRelease(running_code);
+    if (update_code)
+      CFRelease(update_code);
+    if (error) {
+      *error = [NSError errorWithDomain:@"ElectronSquirrelUpdateValidation"
+                                    code:1
+                                userInfo:@{
+                                  NSLocalizedDescriptionKey :
+                                      @"Unable to load code signature "
+                                      @"information for update validation."
+                                }];
+    }
+    return NO;
+  }
+
+  NSString* running_requirement = DesignatedRequirement(running_code);
+  CFRelease(running_code);
+
+  if (running_requirement == nil) {
+    CFRelease(update_code);
+    if (error) {
+      *error = [NSError
+          errorWithDomain:@"ElectronSquirrelUpdateValidation"
+                     code:2
+                 userInfo:@{
+                   NSLocalizedDescriptionKey :
+                       @"Unable to determine designated requirement of "
+                       @"running application."
+                 }];
+    }
+    return NO;
+  }
+
+  SecRequirementRef requirement = NULL;
+  OSStatus status = SecRequirementCreateWithString(
+      (__bridge CFStringRef)running_requirement, kSecCSDefaultFlags,
+      &requirement);
+
+  BOOL valid = NO;
+  if (status == errSecSuccess && requirement != NULL) {
+    // Validate every nested code object (including helper tools, frameworks,
+    // and other bundled executables) against the same requirement that the
+    // currently running application satisfies. kSecCSCheckAllArchitectures
+    // and kSecCSCheckNestedCode ensure that no component of the update can
+    // slip through unsigned or signed by a different identity.
+    SecCSFlags flags = kSecCSCheckAllArchitectures | kSecCSCheckNestedCode |
+                        kSecCSStrictValidate;
+    status = SecStaticCodeCheckValidityWithErrors(update_code, flags,
+                                                   requirement, NULL);
+    valid = (status == errSecSuccess);
+  }
+
+  if (requirement)
+    CFRelease(requirement);
+  CFRelease(update_code);
+
+  if (!valid && error) {
+    *error = [NSError
+        errorWithDomain:@"ElectronSquirrelUpdateValidation"
+                   code:3
+               userInfo:@{
+                 NSLocalizedDescriptionKey :
+                     @"Update package failed code signature validation "
+                     @"against the running application's designated "
+                     @"requirement."
+               }];
+  }
